EXAMPLE: P1AM-100: start/stop with seal-in on discrete I/O modules (Arduino)
language arduino
// P1AM-100: Motor Start/Stop with Seal-in Logic
// Slot 1: Discrete Input Module
//   Channel 1: Start Button (NO - Normally Open)
//   Channel 2: Stop Button (NC - Normally Closed)
// Slot 2: Discrete Output Module
//   Channel 1: Motor Contactor
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  // Wait for P1AM modules to initialize
  while (!P1.init()) {
    ; 
  }
}

void loop() {
  // Read inputs
  // Start is NO: reads HIGH (true) when pressed
  bool startPressed = P1.readDiscrete(inSlot, 1);

  // Stop is NC: reads LOW (false) when pressed (circuit open), HIGH (true) when released
  bool stopReleased = P1.readDiscrete(inSlot, 2);

  // Seal-in logic:
  // Motor runs if (Start is pressed OR Motor is already running) AND (Stop is released)
  // Note: Stop is NC, so we check if it is still "released" (true)
  motorRunning = (startPressed || motorRunning) && stopReleased;

  // Write output
  // Channel 1 drives the motor contactor
  P1.writeDiscrete(motorRunning, outSlot, 1);
}
END
